import React, { useState, useEffect } from 'react';
import './App.css';
import Projects from './components/Projects';
import EventScripting from './components/EventScripting';
import BuildTracking from './components/BuildTracking';
import ShowLayout from './components/ShowLayout';
import Management from './components/Management';
import Login from './components/Login';
import { dbService } from './services/storage';

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [activeTab, setActiveTab] = useState('projects'); // 'projects', 'scripting', 'tracking', 'layout', 'management', 'sync'
  const [selectedProjectId, setSelectedProjectId] = useState(localStorage.getItem('activeProjectId') || null);
  const [activeProject, setActiveProject] = useState(null);
  const [syncTrigger, setSyncTrigger] = useState(0);

  // Background Automatic Synchronization with GitHub
  useEffect(() => {
    if (!isAuthenticated) return;

    const performSilentSync = async () => {
      try {
        const changed = await dbService.fetchFromGitHubSilently();
        if (changed) {
          console.log('Detected database changes from GitHub, reloading...');
          setSyncTrigger(prev => prev + 1);
          if (selectedProjectId) {
            const updatedProj = dbService.getProjectById(selectedProjectId);
            setActiveProject(updatedProj);
          }
        }
      } catch (err) {
        console.warn('Auto-sync check failed:', err);
      }
    };

    performSilentSync();

    const interval = setInterval(performSilentSync, 60000);
    return () => clearInterval(interval);
  }, [isAuthenticated, selectedProjectId]);

  // Load selected project details
  useEffect(() => {
    if (selectedProjectId) {
      const proj = dbService.getProjectById(selectedProjectId);
      setActiveProject(proj);
      localStorage.setItem('activeProjectId', selectedProjectId);
    } else {
      setActiveProject(null);
      localStorage.removeItem('activeProjectId');
    }
  }, [selectedProjectId]);

  const handleSaveProject = async (updatedProj) => {
    const saved = dbService.saveProject(updatedProj);
    setActiveProject(saved);

    // Silent background auto-publish if token is configured
    const config = dbService.getSyncConfig();
    if (config.token) {
      try {
        const editor = localStorage.getItem('gbf_editor_name') || 'Planner';
        await dbService.syncToGitHub(editor);
        console.log('Background auto-published changes to GitHub successfully.');
      } catch (err) {
        console.warn('Background auto-publish failed:', err);
      }
    }
  };

  const handleSelectProjectForEdit = (id) => {
    setSelectedProjectId(id);
    setActiveTab('scripting');
  };

  const handlePublishActiveProject = async () => {
    let editor = localStorage.getItem('gbf_editor_name');
    if (!editor) {
      editor = prompt("Please enter your Editor Name (e.g. Kyle D.) to publish: ");
      if (!editor) return;
      localStorage.setItem('gbf_editor_name', editor);
    }

    const config = dbService.getSyncConfig();
    if (!config.token) {
      alert("Error: No GitHub Access Token configured. Please go to 'Cloud Sync' and save your Token before publishing.");
      return;
    }

    try {
      await dbService.syncToGitHub(editor);
      alert("Success! Changes published to GitHub remote repository.");
    } catch (err) {
      alert(`Publish failed: ${err.message}`);
    }
  };

  if (!isAuthenticated) {
    return (
      <div className="App">
        <header className="App-header" style={{ padding: '20px 40px', borderBottom: '1px solid rgba(255,255,255,0.06)' }}>
          <div className="brand" style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <span style={{ fontSize: '22px' }}>🔥</span>
            <h1 style={{ fontSize: '18px', fontWeight: 'bold', margin: 0, color: '#fff' }}>
              Magic Smoke – Great Balls of Fire
            </h1>
          </div>
        </header>
        <main className="App-main" style={{ padding: '40px' }}>
          <Login onAuthenticated={setIsAuthenticated} />
        </main>
      </div>
    );
  }

  return (
    <div className="App">
      <header className="App-header" style={{ padding: '15px 40px', borderBottom: '1px solid rgba(255,255,255,0.06)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div className="brand" style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <span style={{ fontSize: '24px' }}>🔥</span>
          <div>
            <h1 style={{ fontSize: '18px', fontWeight: 'bold', margin: 0, color: '#fff' }}>
              Magic Smoke – Great Balls of Fire
            </h1>
            {activeProject && (
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginTop: '2px' }}>
                <span style={{ fontSize: '11px', color: 'var(--color-primary-glow)' }}>
                  Active Script: <strong>{activeProject.name} ({activeProject.year})</strong>
                </span>
                <button 
                  className="btn btn-secondary btn-sm" 
                  style={{ padding: '2px 6px', fontSize: '10px', height: '20px', borderColor: 'var(--color-primary-glow)', color: 'var(--color-primary-glow)', background: 'transparent' }}
                  onClick={handlePublishActiveProject}
                >
                  ☁️ Publish Changes
                </button>
              </div>
            )}
          </div>
        </div>

        <nav className="App-nav" style={{ display: 'flex', gap: '12px' }}>
          <button 
            className={`nav-btn ${activeTab === 'projects' ? 'active' : ''}`}
            onClick={() => setActiveTab('projects')}
          >
            📋 Projects List
          </button>
          
          <button 
            className={`nav-btn ${activeTab === 'scripting' ? 'active' : ''}`}
            onClick={() => {
              if (!selectedProjectId) {
                alert('Please select or create a script project first on the Projects page!');
                return;
              }
              setActiveTab('scripting');
            }}
          >
            🎵 Event Scripting
          </button>

          <button 
            className={`nav-btn ${activeTab === 'tracking' ? 'active' : ''}`}
            onClick={() => {
              if (!selectedProjectId) {
                alert('Please select or create a script project first on the Projects page!');
                return;
              }
              setActiveTab('tracking');
            }}
          >
            🛠️ Build Tracking
          </button>

          <button 
            className={`nav-btn ${activeTab === 'layout' ? 'active' : ''}`}
            onClick={() => {
              if (!selectedProjectId) {
                alert('Please select or create a script project first on the Projects page!');
                return;
              }
              setActiveTab('layout');
            }}
          >
            🗺️ Show Layout
          </button>

          <button 
            className={`nav-btn ${activeTab === 'management' ? 'active' : ''}`}
            onClick={() => setActiveTab('management')}
          >
            🗃️ Wholesale Catalog
          </button>

          <button 
            className={`nav-btn ${activeTab === 'sync' ? 'active' : ''}`}
            onClick={() => setActiveTab('sync')}
          >
            ☁️ Cloud Sync
          </button>
        </nav>
      </header>

      <main className="App-main" style={{ padding: '20px 40px' }}>
        {activeTab === 'projects' && (
          <Projects onSelectProject={handleSelectProjectForEdit} syncTrigger={syncTrigger} />
        )}
        
        {activeTab === 'scripting' && activeProject && (
          <EventScripting 
            project={activeProject} 
            onSaveProject={handleSaveProject} 
          />
        )}

        {activeTab === 'tracking' && activeProject && (
          <BuildTracking 
            project={activeProject} 
            onSaveProject={handleSaveProject} 
          />
        )}

        {activeTab === 'layout' && activeProject && (
          <ShowLayout 
            project={activeProject} 
            onSaveProject={handleSaveProject} 
          />
        )}

        {activeTab === 'management' && (
          <Management syncTrigger={syncTrigger} />
        )}

        {activeTab === 'sync' && (
          <Login onAuthenticated={setIsAuthenticated} />
        )}
      </main>
    </div>
  );
}

export default App;
